/* 
  ❌ BAD: Dynamic class names will be purged! 
  Tailwind scanner doesn't know if 'color' is red, blue, or green.
*/
function Button({ color }) {
  return <button className={`bg-${color}-500 p-2`}>Click Me</button>;
}

/* 
  ✅ GOOD: Complete class names must exist in the source code.
*/
function Button({ color }) {
  const colorMap = {
    red: 'bg-red-500',
    blue: 'bg-blue-500',
    green: 'bg-green-500'
  };
  return <button className={`${colorMap[color]} p-2`}>Click Me</button>;
}
